test('real app controller unlocks after another tab sells the mature resident currently held in clean page',()=>{
 const now=Date.now();let seed=rules.createState(now-60000,'app-tabs');seed=rules.reduce(seed,{type:'PLANT',tileId:'tile-0-0',varietyId:'radish'},now-60000).state;seed=rules.reduce(seed,{type:'REVEAL',plantId:seed.plants[0].id},now).state;
 const store=memory();storageFns.saveGame(store,seed,now);const h=appHarness(store),id=seed.plants[0].id;
 h.api.handlePlantControl({phase:'start',plantId:id,events:[]});assert.equal(h.api.ui.activePlantGesture,id);assert.equal(h.api.dirty(),false);
 const external=rules.reduce(seed,{type:'SELL',plantId:id},now).state,head=storageFns.loadGame(store).head,saved=storageFns.saveGame(store,external,now+1,{expectedHead:head});
 h.events.storage({key:storageFns.SAVE_KEY,newValue:saved.head});h.api.handlePlantControl({phase:'end',plantId:id,events:[]});h.api.render();
 assert.equal(h.api.state().plants.length,0);assert.equal(h.api.ui.activePlantGesture,null);assert.ok(h.renders()>0);
});

