test('native Enter and input cannot bypass cloud lock to create a second seed or blueprint beneath the cover',async()=>{for(const building of [false,true]){const h=appHarness(memory(),{realCloud:true});h.api.setReady(true);h.api.ui.visitId=catalogue.DEMO_GARDENS[0].id;await h.api.onAction(building?'panel-blueprint-create':'panel-create');const first=building?'猫咪书屋':'会漂浮的云朵灯',second=building?'用狗狗和露营帐篷造一个小工坊':'爱打鼓的南瓜',form={id:building?'building-idea-form':'idea-form',fields:{idea:first}};h.nodeEvents.garden.submit({target:form,preventDefault(){}});assert.equal(h.api.state().crystals,2);const c=building?h.api.ui.blueprintCreation:h.api.ui.creation,tray=h.nodes.get('tray'),writes=tray.domWrites;h.nodeEvents.garden.input({target:{id:building?'building-idea-input':'idea-input',value:second}});h.nodeEvents.garden.submit({target:{...form,fields:{idea:second}},preventDefault(){}});assert.equal(h.api.state().crystals,2);assert.equal(c.idea,first);assert.equal(tray.domWrites,writes);h.events.keydown({key:'Escape'});}});
