test('wallet pointer double taps grant exactly100 per pair, native aliases no-op and unready or canceled chains never pay',async()=>{const store=memory();storageFns.saveGame(store,rules.createState(Date.now(),'wallet-app'));const h=appHarness(store);h.api.setReady(true);const target={dataset:{action:'coins'}};target.closest=()=>target;const event=(id,detail=1)=>({target,pointerId:id,pointerType:'touch',clientX:20,clientY:30,button:0,detail,timeStamp:id+1});const tap=id=>{h.nodeEvents.garden.pointerdown(event(id));h.nodeEvents.garden.pointerup(event(id));h.nodeEvents.garden.click(event(id));};tap(1);assert.equal(h.api.state().coins,120);tap(2);assert.equal(h.api.state().coins,220);h.nodeEvents.garden.dblclick(event(2,2));assert.equal(h.api.state().coins,220);assert.equal(h.coinEffects.length,1);h.advanceTime(1000);tap(3);tap(4);assert.equal(h.api.state().coins,320);assert.equal(h.api.state().sales,0);assert.equal(h.api.state().crystals,3);tap(5);h.events.blur();tap(6);assert.equal(h.api.state().coins,320);h.events.focus();h.api.setReady(false);tap(7);tap(8);assert.equal(h.api.state().coins,320);await h.api.flushSave();for(let i=0;i<20;i++)await Promise.resolve();assert.equal(storageFns.loadGame(store).state.coins,320);});
test('Escape invalidates a first wallet tap before closing a menu so a later tap cannot finish the canceled pair',async()=>{const store=memory();storageFns.saveGame(store,rules.createState(Date.now(),'wallet-escape'));const h=appHarness(store);h.api.setReady(true);await h.api.onAction('panel-bag');const target={dataset:{action:'coins'}};target.closest=()=>target;const tap=id=>{const e={target,pointerId:id,pointerType:'touch',clientX:20,clientY:30};h.nodeEvents.garden.pointerdown(e);h.nodeEvents.garden.pointerup({...e});};tap(1);h.events.keydown({key:'Escape'});tap(2);assert.equal(h.api.state().coins,120);tap(3);assert.equal(h.api.state().coins,220);});
test('clean save adoption cancels pending outfit status without allowing old completion to clear a newer choice',async()=>{const store=memory();storageFns.saveGame(store,rules.createState(Date.now(),'outfit-adopt'));const ref={image:'assets/outfit-pending.webp'},o={id:'outdoor-utility',front:ref,back:ref,portrait:ref};let finish;const h=appHarness(store,{wardrobeEntries:{'outdoor-utility':o},assetLoad:()=>new Promise(r=>finish=r)});await h.api.onAction('profile');const pending=h.api.onAction('choose-outfit','outdoor-utility');assert.equal(h.api.ui.outfitPending,'outdoor-utility');const latest=storageFns.loadGame(store);storageFns.saveGame(store,{...latest.state,coins:200},Date.now(),{expectedHead:latest.head});h.events.storage({key:storageFns.SAVE_KEY,newValue:store.getItem(storageFns.SAVE_KEY)});assert.equal(h.api.ui.outfitPending,null);finish({});await pending;assert.equal(h.api.ui.outfitPending,null);assert.equal(h.api.state().coins,200);assert.equal(h.api.state().settings.outfitKey,undefined);});
test('a stale source button for a retired demo species does not navigate to an unrelated friend list',async()=>{const h=appHarness(memory());await h.api.onAction('panel-bag');await h.api.onAction('visit-seed-source','demo-cloud_lantern');assert.equal(h.api.ui.panel,'bag');assert.equal(h.api.ui.visitId,null);assert.match(h.nodes.get('toast').textContent,/暂未展出/);});

function growingApp(){const now=Date.now(),store=memory();let s=rules.createState(now,'countdown-app');for(const tileId of ['tile-0-0','tile-1-0'])s=rules.reduce(s,{type:'PLANT',tileId,varietyId:'radish'},now).state;s.coins=0;s.crystals=0;storageFns.saveGame(store,s);let writes=0;const write=store.setItem;store.setItem=(key,value)=>{if(key===storageFns.SAVE_KEY)writes++;write(key,value);};const h=appHarness(store);h.api.setReady(true);h.api.ui.selection={kind:'plant',id:s.plants[0].id};const target=p=>{const b={dataset:{growthPlant:p.id,tileId:p.tileId,varietyId:p.varietyId,plantedAt:String(p.plantedAt),readyAt:String(p.readyAt)}};b.closest=selector=>selector==='[data-growth-plant]'?b:null;return b;};let stamp=0;const tap=(p=s.plants[0])=>{const e={target:target(p),pointerId:++stamp,pointerType:'touch',clientX:20,clientY:30,button:0,detail:1,timeStamp:stamp};h.nodeEvents.garden.pointerdown(e);h.nodeEvents.garden.pointerup({...e});h.nodeEvents.garden.click({...e});};return {h,s,store,tap,writes:()=>writes};}
test('actual context countdown pair matures only its plant, exactly one saved revision, zero currencies and reload preservation',async()=>{const {h,s,store,tap,writes}=growingApp();tap();assert.deepEqual(h.api.state().plants,s.plants);assert.equal(h.api.dirty(),false);tap();h.nodeEvents.garden.dblclick({target:{closest:()=>null}});for(let i=0;i<20;i++)await Promise.resolve();assert.ok(h.api.state().plants[0].readyAt<s.plants[0].readyAt);assert.deepEqual(h.api.state().plants[1],s.plants[1]);assert.equal(h.api.state().coins,0);assert.equal(h.api.state().crystals,0);assert.equal(writes(),1);const restored=storageFns.loadGame(store).state;assert.equal(restored.plants[0].readyAt,h.api.state().plants[0].readyAt);assert.ok(restored.discovered.includes('radish'));tap();tap();for(let i=0;i<20;i++)await Promise.resolve();assert.equal(writes(),1);});
for(const interrupt of ['close','visit','drag','remove'])test(`actual context countdown ${interrupt} invalidates the pending target`,async()=>{const {h,s,tap}=growingApp();tap();if(interrupt==='close'){await h.api.onAction('clear-selection');h.api.ui.selection={kind:'plant',id:s.plants[0].id};}if(interrupt==='visit')h.api.ui.visitId=catalogue.DEMO_GARDENS[0].id;if(interrupt==='remove')h.api.state().plants=[];if(interrupt==='drag')h.nodeEvents.garden.pointercancel({pointerId:1});tap();assert.equal(h.api.state().plants[0]?.readyAt,interrupt==='remove'?undefined:s.plants[0].readyAt);});


test('actual creators use local photo picker, preserve text on rerender, and clear between sessions without saving',async()=>{
 const store=memory();storageFns.saveGame(store,rules.createState(Date.now(),'creation-photo-app'));const before=store.getItem(storageFns.SAVE_KEY),h=appHarness(store);
 await h.api.onAction('panel-create');h.api.ui.creation.idea='一个会唱歌的南瓜';
 const picker=h.document.getElementById('creation-photo-input');let clicks=0;picker.click=()=>clicks++;await h.api.onAction('creation-photo-add');assert.equal(clicks,1);
 const target={id:'creation-photo-input',files:[{name:'a.jpg',type:'image/jpeg',size:2048}],value:'fake-path'};h.nodeEvents.garden.change({target});for(let i=0;i<5;i++)await Promise.resolve();
 assert.equal(target.value,'');assert.equal(h.api.ui.creationPhoto.url,'blob:app-photo-1');assert.equal(h.api.ui.creation.idea,'一个会唱歌的南瓜');h.api.render();assert.equal(h.api.ui.creationPhoto.url,'blob:app-photo-1');
 await h.api.onAction('creation-photo-add');h.nodeEvents.garden.change({target:{id:'creation-photo-input',files:[],value:''}});assert.equal(h.api.ui.creationPhoto.url,'blob:app-photo-1');
 await h.api.onAction('blueprint-create');assert.equal(h.api.ui.creationPhoto.url,null);assert.deepEqual(h.revokedPhotos,['blob:app-photo-1']);
 await h.api.onAction('creation-photo-add');h.nodeEvents.garden.change({target});for(let i=0;i<5;i++)await Promise.resolve();assert.equal(h.api.ui.creationPhoto.url,'blob:app-photo-2');
 await h.api.onAction('creation-photo-remove');assert.equal(h.api.ui.creationPhoto.url,null);assert.deepEqual(h.revokedPhotos,['blob:app-photo-1','blob:app-photo-2']);
 await h.api.onAction('creation-photo-add');h.nodeEvents.garden.change({target});for(let i=0;i<5;i++)await Promise.resolve();await h.api.onAction('close-panel');await h.api.onAction('blueprint-create');assert.equal(h.api.ui.creationPhoto.url,null);
 assert.equal(store.getItem(storageFns.SAVE_KEY),before);assert.equal(h.api.dirty(),false);assert.doesNotMatch(JSON.stringify(h.api.state()),/blob:|a\.jpg/);
});

test('photo picker survives visibility rerender and stale picker returns cannot enter reopened creator',async()=>{
 const h=appHarness(memory());await h.api.onAction('panel-create');h.document.getElementById('creation-photo-input').click=()=>{};
 await h.api.onAction('creation-photo-add');h.document.hidden=true;h.docEvents.visibilitychange();h.document.hidden=false;h.docEvents.visibilitychange();
 const target={id:'creation-photo-input',files:[{name:'cat.jpg',type:'image/jpeg',size:1024}],value:'file'};h.nodeEvents.garden.change({target});for(let i=0;i<5;i++)await Promise.resolve();assert.equal(h.api.ui.creationPhoto.url,'blob:app-photo-1');
 await h.api.onAction('creation-photo-add');await h.api.onAction('close-panel');await h.api.onAction('panel-create');h.nodeEvents.garden.change({target});for(let i=0;i<5;i++)await Promise.resolve();assert.equal(h.api.ui.creationPhoto.url,null);assert.equal(h.photoURLs.length,1);
 await h.api.onAction('creation-photo-add');h.nodeEvents.garden.change({target});for(let i=0;i<5;i++)await Promise.resolve();h.events.pagehide();h.events.pageshow();assert.equal(h.api.ui.creationPhoto.url,null);assert.deepEqual(h.revokedPhotos,['blob:app-photo-1','blob:app-photo-2']);
});


test('actual invitation actions coalesce repeated activation and ignore stale completion after close',async()=>{
 let finish,calls=0;const h=appHarness(memory(),{inviteShare:()=>{calls++;return new Promise(r=>finish=r);}});const before=structuredClone(h.api.state());
 await h.api.onAction('panel-invite');assert.equal(h.api.ui.panel,'invite');const pending=h.api.onAction('invite-share');await h.api.onAction('invite-share');assert.equal(calls,1);
 await h.api.onAction('close-panel');await h.api.onAction('panel-invite');finish('copied');await pending;assert.notEqual(h.nodes.get('toast')?.textContent,'邀请链接已复制');
 const again=h.api.onAction('invite-copy');assert.equal(calls,2);finish('copied');await again;assert.equal(h.nodes.get('toast').textContent,'邀请链接已复制');assert.deepEqual(h.api.state(),before);assert.equal(h.api.dirty(),false);
 await h.api.onAction('close-panel');await h.api.onAction('invite-copy');assert.equal(calls,2);
});
